#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHTML(const std::string& markdown) {
    std::string html;
    std::string line;
    std::istringstream stream(markdown);

    while (std::getline(stream, line)) {
        html += line + "\n";
    }

    return html;
}

int main() {
    std::string markdown = "# Sample Heading\n\nThis is a sample paragraph.\n\nAnother paragraph.";
    std::string html = markdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

